// Checks Plaudit's signature over the raw body, then passes on testimonial.approved only.
// Needs NODE_FUNCTION_ALLOW_BUILTIN=crypto on your n8n server, and the Webhook node's Raw Body option on.
const crypto = require('crypto');
const SECRET = 'whsec_REPLACE_ME'; // Plaudit › Settings › Webhooks › your endpoint › Reveal

const item = $input.first();
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const header = item.json.headers['plaudit-signature'] || '';
const parts = Object.fromEntries(header.split(',').map((p) => p.split('=')));
const t = Number(parts.t);
if (!t || Math.abs(Date.now() / 1000 - t) > 300) throw new Error('Old or missing Plaudit-Signature timestamp');
const expected = crypto.createHmac('sha256', SECRET).update(`${t}.${raw}`).digest('hex');
const a = Buffer.from(expected);
const b = Buffer.from(parts.v1 || '');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) throw new Error('Bad Plaudit signature');

const payload = JSON.parse(raw);
if (payload.event !== 'testimonial.approved') return [];
return [{ json: payload }];
